"""Render the final measurements without treating engineering benchmarks as field evidence."""
import json,statistics
from pathlib import Path
OUT=Path(__file__).resolve().parent
report=json.loads((OUT/'performance-summary.json').read_text(encoding='utf-8'));samples=json.loads((OUT/'performance-samples.json').read_text(encoding='utf-8'))
assert len(samples)==36 and all(r['fcp'] and r['lcp']>0 and r['scroll']['applicable'] for r in samples)
lookup={(r['route'],r['variant']):r for r in report['summary']}
lines=['# Retrospective performance comparison','',f"Chrome {report['browserVersion']}, production builds at 1366×768, light/Uzbek, 4× CPU throttling. Six alternating baseline/redesign pairs per route, fresh disposable contexts, disabled browser cache, remote Google Fonts blocked in both variants. Actual route content and positive paint observations are required before interaction/scroll measurement. Other browser suites were idle.",'','The earliest preserved pre-foundation source is `stage-2/source-before.zip`; Stages 0–1 changed no application source. It was reconstructed in an isolated workspace with the candidate build configuration, public assets and installed lockfile dependencies. Provenance/hashes are in `baseline-provenance.json`. **Stage 0 recorded no timings: these are new retrospective measurements, not historical field data.**','','| Route | Median FCP baseline → redesign | Median LCP baseline → redesign | LCP change | Median DOMContentLoaded baseline → redesign |','|---|---|---|---|---|']
for route in ['/','/exam/practice-1','/admin/bank']:
 a=lookup[route,'baseline']['medians'];b=lookup[route,'redesign']['medians'];delta=(b['lcp']/a['lcp']-1)*100
 lines.append(f"| `{route}` | {a['fcp']:.0f} → {b['fcp']:.0f} ms | {a['lcp']:.0f} → {b['lcp']:.0f} ms | {delta:+.1f}% | {a['domContentLoaded']:.0f} → {b['domContentLoaded']:.0f} ms |")
lines+=['','| Route | Scroll frame p95 baseline → redesign | Frames over 25ms baseline → redesign |','|---|---|---|']
for route in ['/','/exam/practice-1','/admin/bank']:
 a=lookup[route,'baseline'];b=lookup[route,'redesign'];lines.append(f"| `{route}` | {a['scrollFrameP95Ms']:.1f} → {b['scrollFrameP95Ms']:.1f} ms | {a['framesOver25ms']}/{a['measuredFrames']} → {b['framesOver25ms']}/{b['measuredFrames']} |")
a=lookup['/exam/practice-1','baseline'];b=lookup['/exam/practice-1','redesign']
lines+=['',f"Scripted answer selection through two animation frames: median **{a['medianAnswerCommitMs']:.1f} → {b['medianAnswerCommitMs']:.1f} ms**. Every measured answer was present in local storage. This includes synchronous handler/render/frame work; it is **not field INP** or an end-to-end hardware input measurement.",'','| Asset | Baseline → redesign actual file bytes | Baseline → redesign gzip bytes |','|---|---|---|']
def asset(variant,part,suffix):return next(r for r in report['bundles'][variant] if part in r['file'] and r['file'].endswith(suffix))
for label,part,suffix in [('Entry JavaScript','/index-','.js'),('CSS','/index-','.css'),('Teacher chunk','/AdminRoutes-','.js'),('Reference chunk','/DesignSystem-','.js')]:
 a=asset('baseline',part,suffix);b=asset('redesign',part,suffix);lines.append(f"| {label} | {a['bytes']:,} → {b['bytes']:,} | {a['gzipBytes']:,} → {b['gzipBytes']:,} |")
lines+=['','Sizes above count actual UTF-8 file bytes and Python gzip output; Vite console figures use a different reporting/compression path and should not be mixed into these deltas. The entry bundle grew materially with explicit three-language copy and the redesigned workflows. Local preview is not a throttled production network, so these timings do not quantify download cost on slow connections. The release decision must consider the size increase separately.','','## Interpretation and remaining work','','Paint/long-task results vary substantially between runs. Review all raw samples, not only medians. No statistical significance, performance SLO or universal improvement is claimed. Headless rendering, CPU throttling, cached OS resources and synthetic scrolling differ from user hardware. The baseline and redesign also have different content layouts and heights, so the scroll test compares scripted workload on the same route, not an identical scene. It does not measure every glass overlap or touch interaction.','','The first paint probe returned missing observations; it was stopped and preserved as `performance-initial-probe.json`. The first full diagnostic run also sampled one teacher route before its lazy content was ready. Its samples/summary remain under `performance-diagnostic-*` and are excluded from the final table. The final runner waits for the actual route content, requires positive FCP/LCP and requires real scroll content in every sample. CPU profiles were inspected to investigate startup variance; no unsupported optimization or causal attribution is inferred from those two profiles.','','Composed material uses 16px navigation blur and opaque reading surfaces, with an opaque user/OS preference. If final scroll measurements regress, reduce effects in the implicated surface and repeat this matched test before release. Regardless of synthetic medians, verify load/scroll/input on representative lower-powered hardware and a constrained network; review entry-bundle growth and establish a product performance budget. The candidate is not declared faster or production-approved by this report.','','## Individual paint ranges','','| Route / variant | FCP min–max | LCP min–max |','|---|---|---|']
for route in ['/','/exam/practice-1','/admin/bank']:
 for variant in ['baseline','redesign']:
  rows=[r for r in samples if r['route']==route and r['variant']==variant];lines.append(f"| `{route}` / {variant} | {min(r['fcp'] for r in rows):.0f}–{max(r['fcp'] for r in rows):.0f} ms | {min(r['lcp'] for r in rows):.0f}–{max(r['lcp'] for r in rows):.0f} ms |")
lines+=['','## Release finding S9-P01 — unresolved load regression','','The final synthetic comparison records slower median LCP on all three measured routes. Home and Exam regress materially in this environment; entry JavaScript grows from 109,377 to 165,106 gzip bytes. This finding remains **unresolved and requires performance acceptance/remediation before public release**. Functional passes do not waive it. Profiles show startup/initial layout work but do not isolate a single cause. The scroll p95 differences are small and mixed while slow-frame counts fall; these samples do not establish blur as the cause of the load regression. Do not infer that removing glass alone will resolve it. Profile the startup path and evaluate route/copy chunking with a defined budget, then repeat on representative hardware/network conditions.']
(OUT/'PERFORMANCE.md').write_text('\n'.join(lines)+'\n',encoding='utf-8');print('Performance report generated from 36 validated final samples')
